{"version":1,"taskId":"43c7c329-b516-4138-aff1-6143c3895c5b","commandId":"write-adapter-test","operation":"run","headSha":"39e05ff6bd2ffe0fb005bb3ce122a544423e3034","timeoutSeconds":300,"command":"cat > src/obstacles/descriptors.test.ts <<'EOF'
import { describe, expect, it } from 'vitest';
import type { Vec3 } from '../contracts/math';
import type { Hole, ObstacleDescriptor } from '../courses/types';
import {
  buildHoleObstacleRuntime,
  createBumperPad,
  createForceObstacle,
  createMoverConfig,
  createPad,
  createRotatingConfig,
  createZone,
  descriptorBounds,
  descriptorZone,
} from './descriptors';

const v = (x: number, y: number, z: number): Vec3 => ({ x, y, z });
const at = (position: Vec3, size: Vec3) => ({ transform: { position }, size });
const step = { dt: 0.1, elapsed: 1 };

const hole = (obstacles: ObstacleDescriptor[]): Hole => ({
  id: 'test-hole',
  name: 'Test Hole',
  par: 3,
  spawn: v(0, 0.3, 0),
  cup: { position: v(0, 0.1, 10), radius: 0.3, captureDepth: 0.3 },
  bounds: { min: v(-5, -2, -2), max: v(5, 5, 12) },
  surfaces: [{ id: 'floor', transform: { position: v(0, 0, 5) }, shape: 'box', size: v(6, 0.3, 14), material: 'green' }],
  obstacles,
});

describe('obstacle descriptor adapters', () => {
  it('turns the footprint into a zone and axis aligned bounds', () => {
    const descriptor: ObstacleDescriptor = { id: 'z', type: 'fan', ...at(v(1, 2, 3), v(4, 2, 6)), direction: v(0, 1, 0), strength: 5 };

    const zone = descriptorZone(descriptor);
    expect(zone.halfExtents).toEqual(v(2, 1, 3));
    expect(zone.center).toEqual(v(1, 2, 3));
    expect(zone.rotationY).toBe(0);

    expect(descriptorBounds(descriptor)).toEqual({ min: v(-1, 1, 0), max: v(3, 3, 6) });
  });

  it('reads the yaw back from a quaternion rotated footprint', () => {
    const half = Math.SQRT1_2;
    const zone = descriptorZone({
      id: 'r', type: 'conveyor', size: v(2, 1, 2), direction: v(1, 0, 0), strength: 3,
      transform: { position: v(0, 0, 0), rotation: { x: 0, y: half, z: 0, w: half } },
    });
    expect(zone.rotationY).toBeCloseTo(Math.PI / 2, 6);
  });

  it('teleports a ball that enters the entry volume', () => {
    const teleporter = createForceObstacle({
      id: 'tp', type: 'teleporter', ...at(v(0, 0.3, 2), v(2, 1, 2)), exit: v(4, 0.4, 9), exitVelocityScale: 0.5,
    });

    expect(teleporter.update({ position: v(0, 0.3, 6), velocity: v(0, 0, 3) }, step)).toBeNull();
    const effect = teleporter.update({ position: v(0, 0.3, 2), velocity: v(0, 0, 4) }, step);
    expect(effect?.teleport?.position).toEqual(v(4, 0.4, 9));
    expect(effect?.teleport?.velocity).toEqual(v(0, 0, 2));
  });

  it('accelerates a ball inside a fan and drags it along a conveyor', () => {
    const fan = createForceObstacle({ id: 'fan', type: 'fan', ...at(v(0, 1, 0), v(4, 4, 4)), direction: v(0, 3, 0), strength: 10 });
    const lift = fan.update({ position: v(0, 1, 0), velocity: v(0, 0, 0) }, step);
    expect(lift?.deltaVelocity?.y).toBeGreaterThan(0);
    expect(lift?.deltaVelocity?.x).toBeCloseTo(0, 6);

    const belt = createForceObstacle({ id: 'belt', type: 'conveyor', ...at(v(0, 0.3, 0), v(4, 1, 4)), direction: v(1, 0, 0), strength: 2, coupling: 5 });
    const drag = belt.update({ position: v(0, 0.3, 0), velocity: v(0, 0, 0) }, step);
    expect(drag?.deltaVelocity?.x).toBeGreaterThan(0);
  });

  it('maps pad descriptors and static bumpers onto impulse pads', () => {
    const jump = createPad({ id: 'jump', type: 'jump-pad', ...at(v(0, 0.3, 0), v(2, 1, 2)), strength: 6 });
    expect(jump.update(v(0, 0.3, 0), v(1, 0, 0), 0)?.velocity.y).toBeCloseTo(6, 6);

    const boost = createPad({ id: 'boost', type: 'boost-pad', ...at(v(0, 0.3, 0), v(2, 1, 2)), strength: 4, direction: v(0, 0, 1) });
    expect(boost.update(v(0, 0.3, 0), v(0, 0, 1), 0)?.velocity.z).toBeGreaterThan(1);

    const bumper = createBumperPad({ id: 'b', type: 'bumper', ...at(v(0, 0.3, 0), v(1, 1, 1)), restitution: 1.2 });
    expect(bumper?.kind).toBe('bumper');
    expect(createBumperPad({ id: 'w', type: 'wall', ...at(v(0, 0.3, 0), v(1, 1, 1)) })).toBeNull();
  });

  it('builds hazard and field zones with themed defaults', () => {
    const lava = createZone({ id: 'lava', type: 'lava', ...at(v(0, 0.4, 0), v(2, 1, 2)) });
    expect(lava.type).toBe('lava');
    expect(lava.contains(v(0, 0.4, 0))).toBe(true);
    expect(lava.resolveHazard(v(1, 0, 1)).penaltyStrokes).toBe(2);

    const gravity = createZone({ id: 'g', type: 'gravity-zone', ...at(v(0, 2, 0), v(4, 4, 4)), strength: 3 });
    expect(gravity.getForce?.(v(0, 2, 0), v(0, 0, 0), 2)).toEqual(v(0, -6, 0));

    const magnet = createZone({ id: 'm', type: 'magnet-zone', ...at(v(0, 1, 0), v(4, 2, 4)), strength: 10 });
    const pull = magnet.getForce?.(v(1.5, 1, 0), v(0, 0, 0), 1);
    expect(pull!.x).toBeLessThan(0);
  });

  it('splits moving obstacles into rotating arms and linear movers', () => {
    const pendulum: ObstacleDescriptor = {
      id: 'p', type: 'pendulum', ...at(v(0, 1.5, 4), v(0.5, 2, 0.5)),
      motion: { kind: 'swing', axis: v(0, 0, 1), speed: 1.2, armLength: 1.8, swingAngle: 0.8 },
    };
    expect(createRotatingConfig(pendulum)).toMatchObject({ kind: 'pendulum', armLength: 1.8, swingAngle: 0.8 });
    expect(createMoverConfig(pendulum)).toBeNull();

    const slider: ObstacleDescriptor = {
      id: 's', type: 'sliding-wall', ...at(v(0, 0.8, 6), v(3, 1.6, 0.5)),
      motion: { kind: 'translate', axis: v(1, 0, 0), speed: 1, distance: 3, loop: 'ping-pong' },
    };
    expect(createMoverConfig(slider)).toMatchObject({ kind: 'sliding-wall', distance: 3, loop: 'ping-pong' });
    expect(createRotatingConfig(slider)).toBeNull();

    const spinner: ObstacleDescriptor = {
      id: 'sp', type: 'spinner', ...at(v(0, 0.8, 8), v(6, 0.3, 0.4)),
      motion: { kind: 'rotate', axis: v(0, 1, 0), speed: 2 },
    };
    expect(createRotatingConfig(spinner)?.armLength).toBe(3);
  });

  it('groups every obstacle of a hole by the system that drives it', () => {
    const runtime = buildHoleObstacleRuntime(hole([
      { id: 'wall', type: 'wall', ...at(v(-3, 0.5, 5), v(0.3, 1, 12)) },
      { id: 'bumper', type: 'bumper', ...at(v(1, 0.4, 4), v(1, 1, 1)), restitution: 1.1 },
      { id: 'tp', type: 'teleporter', ...at(v(0, 0.3, 3), v(1, 1, 1)), exit: v(0, 0.3, 8) },
      { id: 'pad', type: 'spring-pad', ...at(v(0, 0.3, 6), v(1, 1, 1)), strength: 3 },
      { id: 'lava', type: 'lava', ...at(v(2, 0.3, 7), v(2, 1, 2)) },
      { id: 'gate', type: 'gate', ...at(v(0, 0.8, 9), v(4, 1.4, 0.4)), motion: { kind: 'translate', axis: v(1, 0, 0), speed: 1, distance: 2 } },
    ]));

    expect(runtime.forces.map((f) => f.id)).toEqual(['tp']);
    expect(runtime.pads.map((p) => p.id).sort()).toEqual(['bumper', 'pad']);
    expect(runtime.zones.map((z) => z.id)).toEqual(['lava']);
    expect(runtime.movers.map((m) => m.id)).toEqual(['gate']);
    expect(runtime.rotating).toHaveLength(0);
  });
});
